package mw.sungira.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.view.*;import android.graphics.Color;import android.util.Base64;import java.io.*;
public class MainActivity extends Activity {
 private static final String HOME="https://sungira.netlify.app/";private WebView web;private ValueCallback<Uri[]> chooser;private ProgressBar progress;private LinearLayout errorPanel;private byte[] pendingBytes;private static final int PICK=51,SAVE=52;
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private boolean trusted(String url){try{Uri u=Uri.parse(url);return "https".equals(u.getScheme())&&"sungira.netlify.app".equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(20,63,53));getWindow().setNavigationBarColor(Color.rgb(20,63,53));LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(243,246,241));if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(i.left,i.top,i.right,i.bottom);return insets;});}LinearLayout nav=new LinearLayout(this);nav.setPadding(8,0,8,0);Button home=new Button(this);home.setText("Home");Button group=new Button(this);group.setText("Open group link");Button refresh=new Button(this);refresh.setText("Refresh");nav.addView(home,new LinearLayout.LayoutParams(0,dp(48),1));nav.addView(group,new LinearLayout.LayoutParams(0,dp(48),2));nav.addView(refresh,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(nav);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,4));errorPanel=new LinearLayout(this);errorPanel.setOrientation(LinearLayout.VERTICAL);errorPanel.setPadding(28,28,28,28);TextView error=new TextView(this);error.setText("Sungira needs an internet connection. Check your connection and tap Refresh.");errorPanel.addView(error);root.addView(errorPanel);errorPanel.setVisibility(View.GONE);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(true);s.setJavaScriptCanOpenWindowsAutomatically(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Exports(),"SungiraAndroid");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return navigate(r.getUrl().toString());}public void onPageStarted(WebView v,String url,android.graphics.Bitmap icon){progress.setVisibility(View.VISIBLE);errorPanel.setVisibility(View.GONE);}public void onPageFinished(WebView v,String url){progress.setVisibility(View.GONE);}public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())errorPanel.setVisibility(View.VISIBLE);}});web.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView v,int p){progress.setProgress(p);}public boolean onJsAlert(WebView v,String u,String msg,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("OK",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}public boolean onJsConfirm(WebView v,String u,String msg,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("Continue",(d,w)->result.confirm()).setNegativeButton("Cancel",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> result,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=result;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivityForResult(i,PICK);return true;}public boolean onCreateWindow(WebView v,boolean dialog,boolean gesture,Message msg){if(!gesture)return false;WebView child=new WebView(MainActivity.this);child.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){String url=r.getUrl().toString();if(trusted(url))web.loadUrl(url);else external(url);w.destroy();return true;}});((WebView.WebViewTransport)msg.obj).setWebView(child);msg.sendToTarget();return true;}});home.setOnClickListener(v->web.loadUrl(HOME));refresh.setOnClickListener(v->web.reload());group.setOnClickListener(v->{EditText input=new EditText(this);input.setHint("Paste the Sungira member link");input.setInputType(android.text.InputType.TYPE_TEXT_VARIATION_URI);new AlertDialog.Builder(this).setTitle("Open your group").setView(input).setPositiveButton("Open",(d,w)->{String url=input.getText().toString().trim();if(trusted(url))web.loadUrl(url);else Toast.makeText(this,"Use a https://sungira.netlify.app/ group link",Toast.LENGTH_LONG).show();}).setNegativeButton("Cancel",null).show();});String url=getIntent().getDataString();if(state!=null)web.restoreState(state);else web.loadUrl(trusted(url)?url:HOME);}
 private boolean navigate(String url){if(trusted(url))return false;external(url);return true;}
 private void external(String url){try{Uri u=Uri.parse(url);String scheme=u.getScheme();if("https".equals(scheme)||"mailto".equals(scheme)||"tel".equals(scheme)){startActivity(new Intent(Intent.ACTION_VIEW,u));}}catch(Exception e){Toast.makeText(this,"No app could open this link",Toast.LENGTH_SHORT).show();}}
 public class Exports {@JavascriptInterface public void copyLink(String text){runOnUiThread(()->{if(trusted(web.getUrl()))((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Sungira link",text));});}
 @JavascriptInterface public void printReceipt(String html){runOnUiThread(()->{if(!trusted(web.getUrl())||html.length()>500000)return;WebView printView=new WebView(MainActivity.this);printView.setWebViewClient(new WebViewClient(){public void onPageFinished(WebView v,String url){android.print.PrintManager pm=(android.print.PrintManager)getSystemService(PRINT_SERVICE);pm.print("Sungira receipt",v.createPrintDocumentAdapter("Sungira receipt"),new android.print.PrintAttributes.Builder().build());}});printView.loadDataWithBaseURL(HOME,html,"text/html","UTF-8",null);});}
 @JavascriptInterface public void exportFile(String encoded,String filename,String mime,boolean share,String text){runOnUiThread(()->{if(!trusted(web.getUrl())||encoded==null||encoded.length()>10000000)return;if(!filename.matches("[A-Za-z0-9._-]{1,120}")||!(mime.equals("image/png")||mime.equals("text/html")||mime.startsWith("text/csv")||mime.equals("application/json")||mime.equals("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")))return;try{byte[] bytes=Base64.decode(encoded,Base64.DEFAULT);if(share){File folder=new File(getCacheDir(),"exports");folder.mkdirs();File f=new File(folder,filename);try(FileOutputStream out=new FileOutputStream(f)){out.write(bytes);}Uri uri=Uri.parse("content://mw.sungira.app.files/"+Uri.encode(filename));Intent intent=new Intent(Intent.ACTION_SEND);intent.setType(mime);intent.putExtra(Intent.EXTRA_STREAM,uri);intent.putExtra(Intent.EXTRA_TEXT,text);intent.setClipData(ClipData.newRawUri("Sungira export",uri));intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(intent,"Share Sungira poster"));}else{pendingBytes=bytes;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT);save.addCategory(Intent.CATEGORY_OPENABLE);save.setType(mime);save.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(save,SAVE);}}catch(Exception e){Toast.makeText(MainActivity.this,"The export could not be completed",Toast.LENGTH_LONG).show();}});}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&chooser!=null){chooser.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);chooser=null;}if(request==SAVE){if(result==RESULT_OK&&data!=null&&pendingBytes!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pendingBytes);Toast.makeText(this,"File saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not save file",Toast.LENGTH_SHORT).show();}}pendingBytes=null;}}
 protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);web.saveState(out);}public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}protected void onDestroy(){if(chooser!=null)chooser.onReceiveValue(null);web.removeJavascriptInterface("SungiraAndroid");web.destroy();super.onDestroy();}
}
